"""Write dkr_rule_tests.json: one passing and one failing case per lint rule, plus .dockerignore glob
cases. Shared by materials/dkr-node.js test and materials/dkr_reference.py test."""
import json, os
T = []
def L(rule, expect, df, desc, ignore=""):
    T.append({"kind": "lint", "rule": rule, "expect": expect, "dockerfile": df, "ignore": ignore, "desc": desc})
def G(path, ignore, expect, desc):
    T.append({"kind": "ignore", "path": path, "ignore": ignore, "expect": expect, "desc": desc})
OK_TAIL = "WORKDIR /app\nUSER app\nCMD [\"python\", \"main.py\"]\n"
L("DL3006", True, "FROM python\n" + OK_TAIL, "untagged base fires")
L("DL3006", False, "FROM python:3.12-slim\n" + OK_TAIL, "tagged base passes")
L("DL3006", False, "FROM python:3.12-slim AS b\nFROM b\n" + OK_TAIL, "a stage alias is not an image")
L("DL3007", True, "FROM python:latest\n" + OK_TAIL, ":latest fires")
L("DL3007", False, "FROM python:3.12-slim@sha256:0f08\n" + OK_TAIL, "digest pin passes")
L("DL3000", True, "FROM python:3.12-slim\nWORKDIR app\nUSER app\n", "relative WORKDIR fires")
L("DL3000", False, "FROM python:3.12-slim\nWORKDIR /app\nUSER app\n", "absolute WORKDIR passes")
L("DL3020", True, "FROM python:3.12-slim\nADD app/ /app/\nUSER app\n", "ADD of a local folder fires")
L("DL3020", False, "FROM python:3.12-slim\nADD vendor.tar.gz /opt/\nUSER app\n", "ADD of an archive passes")
L("DL3015", True, "FROM python:3.12-slim\nRUN apt-get update && apt-get install -y curl && rm -rf /var/lib/apt/lists/*\nUSER app\n", "apt without --no-install-recommends fires")
L("DL3015", False, "FROM python:3.12-slim\nRUN apt-get update && apt-get install -y --no-install-recommends curl && rm -rf /var/lib/apt/lists/*\nUSER app\n", "with the flag passes")
L("DL3009", True, "FROM python:3.12-slim\nRUN apt-get update && apt-get install -y --no-install-recommends curl\nUSER app\n", "lists left behind fires")
L("DL3009", False, "FROM python:3.12-slim\nRUN apt-get update \\\n && apt-get install -y --no-install-recommends curl \\\n && rm -rf /var/lib/apt/lists/*\nUSER app\n", "lists removed in the same RUN passes (continuation lines)")
L("DL3042", True, "FROM python:3.12-slim\nRUN pip install -r requirements.txt\nUSER app\n", "pip without --no-cache-dir fires")
L("DL3042", False, "FROM python:3.12-slim\nRUN pip install --no-cache-dir -r requirements.txt\nUSER app\n", "--no-cache-dir passes")
L("DL3042", False, "FROM python:3.12-slim\nRUN --mount=type=cache,target=/root/.cache/pip pip install -r requirements.txt\nUSER app\n", "a cache mount passes")
L("DL3042", False, "FROM python:3.12-slim\nENV PIP_NO_CACHE_DIR=1\nRUN pip install -r requirements.txt\nUSER app\n", "PIP_NO_CACHE_DIR passes")
L("DL3025", True, "FROM python:3.12-slim\nUSER app\nCMD python main.py\n", "shell-form CMD fires")
L("DL3025", False, "FROM python:3.12-slim\nUSER app\nCMD [\"python\", \"main.py\"]\n", "exec-form CMD passes")
L("DL3002", True, "FROM python:3.12-slim\nUSER app\nUSER root\n", "last USER root fires")
L("DL3002", False, "FROM python:3.12-slim\nUSER root\nRUN useradd app\nUSER app\n", "root then app passes")
L("DL3064", True, "FROM python:3.12-slim\nENV DB_PASSWORD=hunter2\nUSER app\n", "a password in ENV fires")
L("DL3064", True, "FROM python:3.12-slim\nARG API_KEY\nUSER app\n", "a key name in ARG fires")
L("DL3064", False, "FROM python:3.12-slim\nENV APP_PORT=8000\nUSER app\n", "an ordinary ENV passes")
L("DKR-ORDER", True, "FROM python:3.12-slim\nWORKDIR /app\nCOPY . .\nRUN pip install --no-cache-dir -r requirements.txt\nUSER app\n", "whole copy before pip fires", ".env\n")
L("DKR-ORDER", False, "FROM python:3.12-slim\nWORKDIR /app\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY . .\nUSER app\n", "requirements first passes", ".env\n")
L("DKR-USER", True, "FROM python:3.12-slim\nWORKDIR /app\n", "no USER in the final stage fires")
L("DKR-USER", False, "FROM python:3.12-slim AS b\nWORKDIR /b\nFROM python:3.12-slim\nUSER app\n", "USER in the final stage passes even if the builder has none")
L("DKR-CONTEXT", True, "FROM python:3.12-slim\nWORKDIR /app\nCOPY . .\nUSER app\n", "whole copy with no .dockerignore fires", "")
L("DKR-CONTEXT", True, "FROM python:3.12-slim\nWORKDIR /app\nCOPY . .\nUSER app\n", "an ignore file that forgets .env still fires", ".git\n.venv\n")
L("DKR-CONTEXT", False, "FROM python:3.12-slim\nWORKDIR /app\nCOPY . .\nUSER app\n", "an ignore file excluding .env passes", ".git\n.env\n")
G(".git/objects/pack/p.pack", ".git\n", True, "a directory pattern excludes its contents")
G("app/__pycache__/x.pyc", "*.pyc\n", False, "*.pyc only matches at the context root (Go filepath.Match)")
G("app/__pycache__/x.pyc", "**/__pycache__\n", True, "** matches any depth")
G("data/keep.csv", "data/\n!data/keep.csv\n", False, "the last matching line wins: an exception re-includes")
G("data/scores.parquet", "data/\n!data/keep.csv\n", True, "the exception does not re-include other files")
G("README.md", "/README.md/\n", True, "leading and trailing slashes are ignored")
G("app/main.py", "# app\n", False, "a comment line excludes nothing")
json.dump(T, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "dkr_rule_tests.json"), "w"), indent=1)
print(len(T), "cases")
